"""Generate the lane report (headline table + verdicts + glossary) from summary.json + run JSONs.

Every number in the output is computed here; prose around the numbers is fixed text.
usage: gen_headline.py  (run gen_report.py first)
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
S = json.loads((HERE / 'summary.json').read_text())
RUNS = HERE.parent / 'runs'


def pct(x, d=4):
    return f'{100 * x:.{d}f}'


def main():
    md = ['# Bank floor vs rank vs online cost — Burgers 2D and Poisson 2D (2026-09-20)', '',
          'Generated by `experiments/bank-floor/reports/gen_headline.py` from the audited run JSONs listed under '
          '*Sources*; no number is typed by hand. Status: **development/validation cohorts plus one confirmation '
          'cohort per PDE opened once; one training seed; sealed paper cohorts untouched — provisional until seeds '
          'are repeated.**', '']
    # ---------------- Poisson headline
    sp, rp = S.get('solve_poisson'), S.get('rep_poisson')
    if sp and rp:
        cg = {k: v for k, v in sp.items() if v['kind'] == 'fom_named'}
        md += ['## Poisson 2D (255 intervals): floor, solved error at $q=R$, paired online cost', '',
               'Solved = the full-bank linear reduced model (row-scaled weak least squares, $M=4R$ tests, QR offline). '
               'Same allocation, same I/O scope (host source in, host dense field out), 7 repetitions, medians. '
               '`confirm256` was opened once, after every bank was frozen.', '',
               '| bank | kind | R | floor dev12 worst % | solved dev12 worst % | solved confirm256 worst % | total ms | '
               + ' | '.join(f'× faster than `{k}`' for k in cg) + ' | × vs direct DST |', '|---|---|---:|---:|---:|---:|---:|'
               + '---:|' * (len(cg) + 1)]
        for tag in ('inc512', 'ft512', 'pod512', 'cat1024', 'pod1024', 'cat2048', 'pod2048'):
            w = sp.get(f'{tag}_weak')
            if not w:
                continue
            kind = 'POD (grid-bound)' if tag.startswith('pod') else 'coordinate network'
            md.append(f"| `{tag}` | {kind} | {w['R']} | {pct(rp[tag]['primary_worst'])} | {pct(w['worst']['dev12'])} | "
                      f"{pct(w['worst']['confirm256'])} | {w['median_total_ms']:.3f} | "
                      + ' | '.join(f"{v['median_total_ms'] / w['median_total_ms']:.1f}" for v in cg.values())
                      + f" | {sp['dst_direct']['median_total_ms'] / w['median_total_ms']:.2f} |")
        md += ['', '| full-order comparator | dev12 worst % | confirm256 worst % | total ms |', '|---|---:|---:|---:|']
        for k, v in sp.items():
            if v['kind'].startswith('fom'):
                md.append(f"| `{k}` ({v['kind']}) | {pct(v['worst']['dev12'])} | {pct(v['worst']['confirm256'])} | {v['median_total_ms']:.3f} |")
        md.append('')
    # ---------------- Burgers headline
    sb, rb = S.get('solve_burgers'), S.get('rep_burgers')
    if rb:
        md += ['## Burgers 2D (256 intervals): floor' + (', solved error at $q=R$, paired online cost' if sb else ''), '']
        if sb:
            foms = {k: v for k, v in sb.items() if v['kind'].startswith('fom')}
            md += ['Solved = identity head on the whole orthonormalised bank, dense exact advection (no EQ rule is '
                   'certified for any new bank, so none is used), unchanged LM query, $M=4R$. Same allocation, '
                   'host field in → six host fields out, 5 repetitions, medians.', '',
                   '| bank | kind | R | floor dev6 worst % | floor hold64 worst % | solved dev6 all-times % | solved dev6 evolved % | '
                   'solved confirm all-times % | total ms | ' + ' | '.join(f'cost / `{k}`' for k in foms) + ' |',
                   '|---|---|---:|---:|---:|---:|---:|---:|---:|' + '---:|' * len(foms)]
            for tag in ('inc512', 'ft512', 'pod512', 'cat1024', 'pod1024', 'cat2048', 'pod2048'):
                w = sb.get(f'{tag}_full')
                if not w:
                    continue
                kind = 'POD (grid-bound)' if tag.startswith('pod') else 'coordinate network'
                md.append(f"| `{tag}` | {kind} | {w['R']} | {pct(rb[tag]['primary_worst'])} | {pct(rb[tag]['large_worst']['hold64'])} | "
                          f"{pct(w['worst_all']['dev6'])} | {pct(w['worst_evolved']['dev6'])} | {pct(w['worst_all']['confirm'])} | "
                          f"{w['median_total_ms']:.0f} | "
                          + ' | '.join(f"{w['median_total_ms'] / v['median_total_ms']:.1f}×" for v in foms.values()) + ' |')
            md += ['', '| full-order comparator | dev6 worst all-times % (same-grid) | confirm worst % | total ms |', '|---|---:|---:|---:|']
            for k, v in foms.items():
                md.append(f"| `{k}` | {pct(v['worst_all']['dev6'])} | {pct(v['worst_all']['confirm'])} | {v['median_total_ms']:.1f} |")
            md.append('')
        else:
            md += ['| bank | R | floor dev6 worst % | floor hold64 worst % | vs inc512 |', '|---|---:|---:|---:|---:|']
            for tag in ('inc512', 'ft512', 'pod512', 'cat1024', 'pod1024', 'cat2048', 'pod2048'):
                md.append(f"| `{tag}` | {rb[tag]['R']} | {pct(rb[tag]['primary_worst'])} | {pct(rb[tag]['large_worst']['hold64'])} | {rb[tag]['improvement_vs_inc512']:.2f}× |")
            md.append('')
    # ---------------- gate P1
    md += ['## Gate P1 (pre-registered: ≥ 3× on the primary cohort and ≥ 2× on the large cohorts, full rank)', '',
           '| PDE | promoted | not promoted |', '|---|---|---|']
    for key, name in (('rep_poisson', 'Poisson'), ('rep_burgers', 'Burgers')):
        if S.get(key):
            arms = {k: v for k, v in S[key].items() if not any(x in k for x in ('raw', '_sub', 'random', 'inc'))}
            md.append(f"| {name} | " + ', '.join(f'`{k}` ({v["improvement_vs_inc512"]:.1f}×)' for k, v in arms.items() if v['p1_promoted'])
                      + ' | ' + ', '.join(f'`{k}` ({v["improvement_vs_inc512"]:.2f}×)' for k, v in arms.items() if not v['p1_promoted']) + ' |')
    md += ['', (HERE / 'tables.generated.md').read_text(), '## Sources', '', '```json', json.dumps(S['sources'], indent=1), '```', '',
           (HERE / 'glossary.md').read_text()]
    (HERE / '2026-09-20-bank-floor-vs-rank-vs-online-cost.md').write_text('\n'.join(md) + '\n')
    print('\n'.join(md[:60]))


if __name__ == '__main__':
    main()
